    if(b.hasAttribute('data-complete')){const id=b.dataset.complete;if(currentComplete(id)){state.completed=state.completed.filter(x=>x!==id);delete state.readRevisions[id];}else{if(!done(id))state.completed.push(id);state.readRevisions[id]=lessonRevision(id);}save();const y=window.scrollY;render();window.scrollTo(0,y);toast(currentComplete(id)?'Reading marked complete.':'Reading marked unread.');}
